const staticData = $getWorkflowStaticData('global');
staticData.listings = [];

// The HTTP node replaces the item with the response body, so counters passed
// through it as item fields do not survive. Page and retry state live here.
staticData.currentPage = 1;
staticData.searchAttempt = 0;
staticData.retryPage = null;
staticData.listingAttempt = 0;
staticData.retryAdId = null;

return [{
  json: {
    page: 1,
    attempt: 0
  }
}];

const staticData = $getWorkflowStaticData('global');
const html = $input.first().json.data || '';
const config = $('Config').first().json;
const maxPages = config.maxPages;
const testMode = config.testMode;
const priceFrom = config.priceFrom;

// Same both-formats price parsing as the detail parser: "495.000 €" and
// "116,000 €" both occur, so the last separator group's length decides.
function parsePrice(numStr) {
  const lastSep = Math.max(numStr.lastIndexOf('.'), numStr.lastIndexOf(','));
  if (lastSep === -1) return parseFloat(numStr);
  const tail = numStr.slice(lastSep + 1);
  if (tail.length === 3) return parseFloat(numStr.replace(/[.,]/g, ''));
  const intPart = numStr.slice(0, lastSep).replace(/[.,]/g, '');
  return parseFloat(`${intPart}.${tail}`);
}

// The results page carries a promoted/sponsored strip at the top whose cards use
// exactly the same markup as real results but ignore the search filters - rentals
// and sub-100k ads appear despite sell=1&pricefrom=100000. There is no container
// class that separates them, so read each card's own price and drop the ones that
// do not match, rather than paying ~6s per listing to fetch and discard them later.
const cardRegex = /<a[^>]+href="\/AdDetails\?ad=(\d+)"[^>]*class="[^"]*SearchAdTitle[^"]*"/gi;
const priceRegex = /([\d]{1,3}(?:[.,]\d{3})*(?:[.,]\d+)?)\s*(€|МКД|ден\.?)/i;

const seen = new Set();
let cardsOnPage = 0;
let keptOnPage = 0;
let skippedOnPage = 0;
const skippedSamples = [];

let m;
while ((m = cardRegex.exec(html)) !== null) {
  const adId = m[1];
  cardsOnPage += 1;
  if (seen.has(adId)) continue;
  seen.add(adId);

  // A card's price follows its title link within roughly 600-700 chars. Stop at
  // the next card's link so a card with no price cannot borrow its neighbour's.
  const nextLinkIdx = html.indexOf('AdDetails?ad=', m.index + 20);
  const windowEnd = Math.min(m.index + 1500, nextLinkIdx === -1 ? html.length : nextLinkIdx);
  const priceMatch = html.slice(m.index, windowEnd).match(priceRegex);
  let priceNumeric = null;
  let currency = '';
  if (priceMatch) {
    currency = /€/.test(priceMatch[2]) ? '€' : 'МКД';
    priceNumeric = parsePrice(priceMatch[1]);
  }

  // Cards with no visible price (e.g. "по договор") are kept - the detail page
  // decides. Cards with a price that fails the filter are dropped here.
  const keep = priceNumeric === null || (currency === '€' && priceNumeric >= priceFrom);

  if (!keep) {
    skippedOnPage += 1;
    if (skippedSamples.length < 5) {
      skippedSamples.push(`${adId}: ${priceMatch[1]} ${priceMatch[2]}`);
    }
    continue;
  }

  keptOnPage += 1;
  if (!staticData.listings.some((l) => l.adId === adId)) {
    staticData.listings.push({ adId, url: `https://reklama5.mk/AdDetails?ad=${adId}` });
  }
}

// The HTTP node replaces the item with the response body, so a page counter
// passed along as an item field is destroyed on every fetch - it lives in
// static data instead. Reading it from the item made this loop never end.
const currentPage = staticData.currentPage || 1;
const nextPage = currentPage + 1;
staticData.currentPage = nextPage;
staticData.searchAttempt = 0;

// Pagination continues on cards present, not cards kept, so a page that happens
// to be entirely filtered out does not end the run early.
const hasMore = cardsOnPage > 0;

// Test Mode only ever looks at search-results page 1, then stops paginating
const shouldContinuePaginating = testMode ? false : (hasMore && nextPage <= maxPages);

return [{
  json: {
    page: nextPage,
    attempt: 0,
    scannedPage: currentPage,
    foundOnPage: cardsOnPage,
    keptOnPage,
    skippedOnPage,
    skippedSamples,
    totalCollected: staticData.listings.length,
    shouldContinuePaginating
  }
}];

const staticData = $getWorkflowStaticData('global');
const raw = $input.first().json || {};
const maxRetries = $('Config').first().json.maxRetries;

// The HTTP node's error output does not carry the original item's fields, so
// neither the page number nor the attempt count survives a failed fetch. Both
// are tracked in static data - reading attempt off the item made it always 1,
// which would have retried a persistently failing page forever.
const page = staticData.currentPage || 1;
if (staticData.retryPage !== page) {
  staticData.retryPage = page;
  staticData.searchAttempt = 0;
}
staticData.searchAttempt = (staticData.searchAttempt || 0) + 1;
const attempt = staticData.searchAttempt;

const errorMessage =
  (raw.error && (raw.error.message || raw.error)) ||
  raw.message ||
  'Барањето не успеа (непозната грешка)';

return [{
  json: {
    page,
    attempt,
    lastError: String(errorMessage),
    shouldRetrySearch: attempt <= maxRetries
  }
}];

const raw = $input.first().json;
const searchUrl = `https://reklama5.mk/Search?city=&cat=157&q=&sell=1&buy=0&rent=0&includeforrent=0&trade=0&includeOld=0&includeNew=0&cargoReady=0&DDVIncluded=0&private=0&company=0&page=${raw.page}&SortByPrice=0&pricefrom=100000&priceto=&pageView=`;

return [{
  json: {
    'Чекор': `Преземање страница за пребарување ${raw.page}`,
    'Порака за грешка': raw.lastError || 'Непозната грешка',
    'Линк до оглас': searchUrl,
    'Датум и време': new Date().toISOString(),
    page: raw.page
  }
}];

const staticData = $getWorkflowStaticData('global');
const config = $('Config').first().json;

// Page number lives in static data - see Parse Search Page
const currentPage = staticData.currentPage || 1;
const nextPage = currentPage + 1;
staticData.currentPage = nextPage;
staticData.searchAttempt = 0;

const shouldContinuePaginating = config.testMode ? false : (nextPage <= config.maxPages);

return [{
  json: {
    page: nextPage,
    attempt: 0,
    shouldContinuePaginating
  }
}];

const staticData = $getWorkflowStaticData('global');
const listings = staticData.listings || [];
return listings.map(l => ({ json: l }));

const existingRows = $input.all().map((i) => i.json);

// Scan every cell of every row rather than looking up one exact header name.
// Keying off 'Линк до оглас' meant that any drift in that header - a trailing
// space, different encoding, a renamed column - silently produced an empty set,
// so every listing looked new and got appended again.
const existingIds = new Set();
for (const row of existingRows) {
  for (const value of Object.values(row || {})) {
    const m = String(value == null ? '' : value).match(/[?&]ad=(\d+)/);
    if (m) {
      existingIds.add(m[1]);
      break;
    }
  }
}

const collected = $('Get Collected Listings').all().map((i) => i.json);
const matchedCount = collected.filter((l) => existingIds.has(l.adId)).length;
let newListings = collected.filter((l) => !existingIds.has(l.adId));

// Counted before Test Mode's cap - capping first hides whether dedup matched
// anything at all, which is the thing worth being sure about.
const newBeforeCap = newListings.length;

const testMode = $('Config').first().json.testMode;
if (testMode) {
  newListings = newListings.slice(0, 10);
}

// Counts are attached to the first item so a dedup problem is visible in the
// node output instead of only showing up as duplicate rows in the sheet.
return newListings.map((l, idx) => ({
  json: {
    ...l,
    attempt: 0,
    ...(idx === 0
      ? {
          _existingRowsRead: existingRows.length,
          _existingIdsFound: existingIds.size,
          _collectedThisRun: collected.length,
          _alreadyStoredMatched: matchedCount,
          _newBeforeCap: newBeforeCap,
          _newAfterCap: newListings.length
        }
      : {})
  }
}));

const html = $json.data || '';

// The HTTP node replaces the item with the response body, so adId/url do not
// survive the fetch - read them back off the current Loop Listings batch item.
const loopItem = $('Loop Listings').first().json || {};
const url = loopItem.url || $json.url || '';
const adId = loopItem.adId || $json.adId || (url.match(/ad=(\d+)/) || [])[1] || '';

function decodeEntities(str) {
  return str
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .trim();
}
function stripTags(str) {
  return decodeEntities(str.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ')).trim();
}

// Reklama5 shows both "495.000 €" and "116,000 €" styles, so the separator
// alone does not say thousands vs decimal - decide by the length of the last group.
function parsePrice(numStr) {
  const lastSep = Math.max(numStr.lastIndexOf('.'), numStr.lastIndexOf(','));
  if (lastSep === -1) return parseFloat(numStr);
  const tail = numStr.slice(lastSep + 1);
  if (tail.length === 3) return parseFloat(numStr.replace(/[.,]/g, ''));
  const intPart = numStr.slice(0, lastSep).replace(/[.,]/g, '');
  return parseFloat(`${intPart}.${tail}`);
}

function pad(n) { return String(n).padStart(2, '0'); }
function formatDate(d) {
  return `${pad(d.getDate())}.${pad(d.getMonth() + 1)}.${d.getFullYear()}`;
}

// Reklama5 serves this page in English to non-browser clients even with an
// Accept-Language: mk header, so every anchor below is a CSS class or an icon
// class rather than localised label text.
const cleanHtml = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ');

// --- Title: <h5 class="card-title" ...> ---
let title = '';
const titleMatch = cleanHtml.match(/<h5[^>]*class="[^"]*card-title[^"]*"[^>]*>([\s\S]*?)<\/h5>/i);
if (titleMatch) title = stripTags(titleMatch[1]);
if (!title) {
  const tagTitle = cleanHtml.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (tagTitle) title = stripTags(tagTitle[1]);
}

// --- Price: <h5 class="mb-0 defaultBlue" ...> ---
const priceRegex = /([\d]{1,3}(?:[.,]\d{3})*(?:[.,]\d+)?)\s*(€|МКД|ден\.?)/i;
let priceRaw = '';
let priceCurrency = '';
let priceNumeric = null;

const priceBlock = cleanHtml.match(/<h5[^>]*class="[^"]*defaultBlue[^"]*"[^>]*>([\s\S]*?)<\/h5>/i);
let priceMatch = priceBlock ? stripTags(priceBlock[1]).match(priceRegex) : null;
if (!priceMatch) priceMatch = stripTags(cleanHtml).match(priceRegex);
if (priceMatch) {
  priceRaw = `${priceMatch[1]} ${priceMatch[2]}`.trim();
  priceCurrency = /€/.test(priceMatch[2]) ? '€' : 'МКД';
  priceNumeric = parsePrice(priceMatch[1]);
}

// --- Date + location: <span><small>DATE</small></span><br /><p>LOCATION</p> ---
// Searched from the title onwards so earlier <span><small> blocks cannot win.
let datePostedRaw = '';
let datePosted = '';
let location = '';
const fromTitle = cleanHtml.slice(titleMatch ? titleMatch.index : 0);
const dateLocMatch = fromTitle.match(
  /<span>\s*<small>([\s\S]{0,80}?)<\/small>\s*<\/span>\s*<br\s*\/?>\s*<p>([\s\S]{0,120}?)<\/p>/i
);
if (dateLocMatch) {
  datePostedRaw = stripTags(dateLocMatch[1]);
  location = stripTags(dateLocMatch[2]);
}

// "Today 13:00" / "Денес 13:00" is useless once the row is a few days old,
// so resolve relative dates to a real one and keep the clock time.
datePosted = datePostedRaw;
const relMatch = datePostedRaw.match(/^(Today|Денес|Yesterday|Вчера)\s*(\d{1,2}:\d{2})?/i);
if (relMatch) {
  const d = new Date();
  if (/Yesterday|Вчера/i.test(relMatch[1])) d.setDate(d.getDate() - 1);
  datePosted = `${formatDate(d)}${relMatch[2] ? ' ' + relMatch[2] : ''}`;
}

// --- Seller name: <h5 class="my-0">NAME</h5> in the right-hand sidebar ---
let sellerName = '';
const nameMatch = cleanHtml.match(/<h5[^>]*class="[^"]*my-0[^"]*"[^>]*>([\s\S]*?)<\/h5>/i);
if (nameMatch) sellerName = stripTags(nameMatch[1]);

// --- Agency vs private ---
// The brief's "any image = agency" rule does not hold: every advertiser block
// carries a static /Content/images/cert.png "Verified Advertiser" badge. Treat
// only a non-static image (an uploaded logo) or an agency word as the signal.
let sellerType = 'Приватно лице';
let sellerTypeSignal = 'default-no-signal';
if (nameMatch) {
  const blockStart = Math.max(0, nameMatch.index - 1500);
  const sellerBlock = cleanHtml.slice(blockStart, nameMatch.index + 600);
  // \ssrc= so that data-src= (the lazy-loaded Google Maps image) is not read as a logo
  const imgs = sellerBlock.match(/<img\b[^>]*\ssrc="([^"]*)"[^>]*>/gi) || [];
  const uploadedLogo = imgs.some((tag) => {
    const src = (tag.match(/\ssrc="([^"]*)"/i) || [])[1] || '';
    return src && !/\/Content\/images\//i.test(src);
  });
  const agencyWord = /агенциј|agencij|agency|недвижнин|nekretnin|real\s*estate|d\.?o\.?o\.?/i.test(sellerName);
  if (agencyWord) {
    sellerType = 'Агенција';
    sellerTypeSignal = 'name-keyword';
  } else if (uploadedLogo) {
    sellerType = 'Агенција';
    sellerTypeSignal = 'uploaded-logo';
  } else {
    sellerTypeSignal = 'no-logo-no-keyword';
  }
}

// --- Phone: anchored on the phone icon in the sidebar ---
let phoneRaw = '';
let phoneSource = 'sidebar';
const sidebarPhoneRegex = /0\d{1,2}[\s\/\-]?\d{3}[\s\/\-]?\d{3,4}/;
const phoneIconIdx = cleanHtml.search(/fa-phone-alt/i);
if (phoneIconIdx !== -1) {
  const afterIcon = stripTags(cleanHtml.slice(phoneIconIdx, phoneIconIdx + 400));
  const m = afterIcon.match(sidebarPhoneRegex);
  if (m) phoneRaw = m[0].trim();
}

// Fallback: scan the ad text. URLs are stripped first because the embedded
// Google Maps coordinates (center=42.0069480002806,...) otherwise match as phones.
if (!phoneRaw) {
  const textOnly = stripTags(cleanHtml.replace(/https?:\/\/[^\s"'<>]+/g, ' ').replace(/viber:\/\/[^\s"'<>]+/g, ' '));
  const strictMobile = /\b07\d[\s\/\-]?\d{3}[\s\/\-]?\d{3}\b/;
  const m = textOnly.match(strictMobile);
  if (m) {
    phoneRaw = m[0].trim();
    phoneSource = 'fallback-scan';
  } else {
    phoneSource = 'not-found';
  }
}

const phoneDigits = phoneRaw.replace(/\D/g, '');
let phoneDisplay = phoneRaw;
if (phoneDigits && phoneDigits !== phoneRaw) {
  phoneDisplay = `${phoneRaw} (${phoneDigits})`;
}

const fullUrl = url.startsWith('http')
  ? url
  : `https://reklama5.mk${url.startsWith('/') ? '' : '/'}${url}`;
const isAllowedHost = fullUrl.startsWith('https://reklama5.mk/');

const priceFrom = $('Config').first().json.priceFrom;
const isValidListing =
  priceCurrency === '€' && priceNumeric !== null && priceNumeric >= priceFrom && isAllowedHost;

return {
  json: {
    adId,
    title,
    priceRaw,
    priceCurrency,
    priceNumeric,
    location,
    datePosted,
    datePostedRaw,
    sellerName,
    sellerType,
    sellerTypeSignal,
    phoneRaw,
    phoneDigits,
    phoneDisplay,
    phoneSource,
    url: fullUrl,
    isAllowedHost,
    isValidListing,
    scrapedAt: new Date().toISOString()
  }
};

return {
  json: {
    'Наслов на оглас': $json.title,
    'Цена': $json.priceRaw,
    'Локација': $json.location,
    'Датум на објавување': $json.datePosted,
    'Име на продавач/агенција': $json.sellerName,
    'Телефон': $json.phoneDisplay,
    'Приватно/Агенција': $json.sellerType,
    'Линк до оглас': $json.url,
    'Датум на извлекување': $json.scrapedAt
  }
};

return {
  json: {
    'Чекор': 'Филтер на валута/цена/домен',
    'Порака за грешка': `Исклучено: цена="${$json.priceRaw}" валута=${$json.priceCurrency || 'непозната'} износ=${$json.priceNumeric} дозволен домен=${$json.isAllowedHost}`,
    'Линк до оглас': $json.url,
    'Датум и време': $json.scrapedAt || new Date().toISOString()
  }
};

const staticData = $getWorkflowStaticData('global');
const raw = $input.first().json || {};
const maxRetries = $('Config').first().json.maxRetries;

// The HTTP node's error output drops the original item's fields, so read the
// listing back off the current batch and keep the attempt count in static data,
// resetting it whenever the loop moves on to a different ad.
const loopItem = $('Loop Listings').first().json || {};
const url = loopItem.url || raw.url || '';
const adId = loopItem.adId || (url.match(/ad=(\d+)/) || [])[1] || '';

if (staticData.retryAdId !== adId) {
  staticData.retryAdId = adId;
  staticData.listingAttempt = 0;
}
staticData.listingAttempt = (staticData.listingAttempt || 0) + 1;
const attempt = staticData.listingAttempt;

const errorMessage =
  (raw.error && (raw.error.message || raw.error)) ||
  raw.message ||
  'Барањето не успеа (непозната грешка)';

return [{
  json: {
    url,
    adId,
    attempt,
    lastError: String(errorMessage),
    shouldRetryListing: attempt <= maxRetries
  }
}];

const raw = $input.first().json;
const maxRetries = $('Config').first().json.maxRetries;

return [{
  json: {
    'Чекор': `Преземање на детали за оглас (по ${maxRetries} обиди)`,
    'Порака за грешка': raw.lastError || 'Непозната грешка',
    'Линк до оглас': raw.url || '',
    'Датум и време': new Date().toISOString()
  }
}];
